/* Shashka Game - Canvas Board Renderer */

'use strict';

class Board {
  constructor(canvasId) {
    this.canvas = document.getElementById(canvasId);
    this.ctx = this.canvas ? this.canvas.getContext('2d') : null;
    this.size = 8;
    this.cell = 0;
    this.board = [];
    this.selected = null;       // {row, col}
    this.validMoves = [];       // [{row, col}]
    this.flipped = false;       // for black player perspective
    this.onSquareClick = null;  // callback(row, col)
    this.theme = { light: '#f0d9b5', dark: '#b58863' };

    if (this.canvas) {
      this.setupCanvas();
      this.bindEvents();
    }
  }

  setupCanvas() {
    const rect = this.canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const displaySize = Math.min(rect.width || 440, 440);
    this.canvas.width = displaySize * dpr;
    this.canvas.height = displaySize * dpr;
    this.ctx.scale(dpr, dpr);
    this.cell = displaySize / this.size;
    this.displaySize = displaySize;
  }

  setTheme(light, dark) {
    this.theme = { light, dark };
    this.render();
  }

  setBoard(board) {
    this.board = board;
    this.render();
  }

  setFlipped(flipped) {
    this.flipped = flipped;
    this.render();
  }

  /* Convert display coords to board coords (handles flipping) */
  toBoardCoords(row, col) {
    if (this.flipped) {
      return { row: this.size - 1 - row, col: this.size - 1 - col };
    }
    return { row, col };
  }

  bindEvents() {
    const handler = (clientX, clientY) => {
      const rect = this.canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      let col = Math.floor(x / this.cell);
      let row = Math.floor(y / this.cell);
      const coords = this.toBoardCoords(row, col);
      if (this.onSquareClick) this.onSquareClick(coords.row, coords.col);
    };

    this.canvas.addEventListener('click', (e) => handler(e.clientX, e.clientY));
    this.canvas.addEventListener('touchstart', (e) => {
      e.preventDefault();
      const t = e.touches[0];
      handler(t.clientX, t.clientY);
    }, { passive: false });
  }

  select(row, col, validMoves) {
    this.selected = { row, col };
    this.validMoves = validMoves || [];
    this.render();
  }

  clearSelection() {
    this.selected = null;
    this.validMoves = [];
    this.render();
  }

  /* Main render loop */
  render() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.displaySize, this.displaySize);

    for (let r = 0; r < this.size; r++) {
      for (let c = 0; c < this.size; c++) {
        const disp = this.toBoardCoords(r, c);
        this.drawSquare(r, c, disp.row, disp.col);
      }
    }

    // Draw pieces
    if (this.board && this.board.length) {
      for (let r = 0; r < this.size; r++) {
        for (let c = 0; c < this.size; c++) {
          const piece = this.board[r][c];
          if (piece && piece !== 0) {
            this.drawPiece(r, c, piece);
          }
        }
      }
    }
  }

  drawSquare(boardRow, boardCol, dispRow, dispCol) {
    const ctx = this.ctx;
    const isDark = (boardRow + boardCol) % 2 === 1;
    const x = dispCol * this.cell;
    const y = dispRow * this.cell;

    ctx.fillStyle = isDark ? this.theme.dark : this.theme.light;
    ctx.fillRect(x, y, this.cell, this.cell);

    // Highlight selected
    if (this.selected && this.selected.row === boardRow && this.selected.col === boardCol) {
      ctx.fillStyle = 'rgba(52, 199, 89, 0.45)';
      ctx.fillRect(x, y, this.cell, this.cell);
    }

    // Highlight valid moves
    const isValid = this.validMoves.some((m) => m.row === boardRow && m.col === boardCol);
    if (isValid) {
      ctx.fillStyle = 'rgba(52, 199, 89, 0.7)';
      ctx.beginPath();
      ctx.arc(x + this.cell / 2, y + this.cell / 2, this.cell * 0.16, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  drawPiece(boardRow, boardCol, piece) {
    const ctx = this.ctx;
    const disp = this.toBoardCoords(boardRow, boardCol);
    const cx = disp.col * this.cell + this.cell / 2;
    const cy = disp.row * this.cell + this.cell / 2;
    const radius = this.cell * 0.38;

    const isWhite = (piece === 2 || piece === 4);
    const isKing = (piece === 3 || piece === 4);

    // Shadow
    ctx.beginPath();
    ctx.arc(cx, cy + 2, radius, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    ctx.fill();

    // Gradient body
    const grad = ctx.createRadialGradient(cx - radius / 3, cy - radius / 3, radius / 4, cx, cy, radius);
    if (isWhite) {
      grad.addColorStop(0, '#ffffff');
      grad.addColorStop(1, '#d0d0d0');
    } else {
      grad.addColorStop(0, '#555555');
      grad.addColorStop(1, '#1a1a1a');
    }
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();

    // Border ring
    ctx.lineWidth = 2;
    ctx.strokeStyle = isWhite ? '#aaaaaa' : '#000000';
    ctx.stroke();

    // King crown
    if (isKing) {
      ctx.fillStyle = '#ffd700';
      ctx.font = (radius * 1.1) + 'px serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('♔', cx, cy);
    }
  }

  /* Animate a piece moving from one square to another */
  animateMove(fromRow, fromCol, toRow, toCol, piece, callback) {
    const start = performance.now();
    const duration = 250;
    const fromDisp = this.toBoardCoords(fromRow, fromCol);
    const toDisp = this.toBoardCoords(toRow, toCol);

    const fx = fromDisp.col * this.cell + this.cell / 2;
    const fy = fromDisp.row * this.cell + this.cell / 2;
    const tx = toDisp.col * this.cell + this.cell / 2;
    const ty = toDisp.row * this.cell + this.cell / 2;

    const step = (now) => {
      const t = Math.min(1, (now - start) / duration);
      const ease = 1 - Math.pow(1 - t, 3);
      this.render();
      const cx = fx + (tx - fx) * ease;
      const cy = fy + (ty - fy) * ease;
      this._drawPieceAt(cx, cy, piece);
      if (t < 1) {
        requestAnimationFrame(step);
      } else if (callback) {
        callback();
      }
    };
    requestAnimationFrame(step);
  }

  _drawPieceAt(cx, cy, piece) {
    const ctx = this.ctx;
    const radius = this.cell * 0.38;
    const isWhite = (piece === 2 || piece === 4);
    const grad = ctx.createRadialGradient(cx - radius / 3, cy - radius / 3, radius / 4, cx, cy, radius);
    if (isWhite) { grad.addColorStop(0, '#fff'); grad.addColorStop(1, '#d0d0d0'); }
    else { grad.addColorStop(0, '#555'); grad.addColorStop(1, '#1a1a1a'); }
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();
  }
}

window.Board = Board;
